/**
 * Reflection loop (TradingAgents pattern, adapted for prediction markets):
 * every settled position with a model view becomes a terse, falsifiable
 * lesson about what the model got right or wrong, and lessons for a
 * category are re-injected wherever the next decision about that category
 * is made (/analyze output today; any future decision prompt).
 *
 * Lessons are generated by the fast LLM when a key is available, with a
 * deterministic fallback so the loop never stalls on a missing provider.
 */
import type { Database } from 'bun:sqlite';
import { categoryOf } from './calibration.js';

export interface LessonRow {
  id: number;
  ticker: string;
  event_ticker: string;
  category: string;
  settled_time: string;
  model_prob: number;
  market_prob: number | null;
  outcome: number;
  realized_pnl: number;
  lesson: string;
  source: string;
}

export type LessonLlm = (prompt: string) => Promise<string>;

interface PendingSettlement {
  ticker: string;
  event_ticker: string;
  settled_time: string;
  model_prob_entry: number;
  market_prob_entry: number | null;
  edge_entry: number | null;
  market_result: string;
  realized_pnl: number;
  drivers_json: string | null;
}

/** Settlements with a model view that don't have a lesson yet. */
export function getPendingReflections(db: Database, limit = 10): PendingSettlement[] {
  return db
    .prepare(
      `SELECT s.ticker, s.event_ticker, s.settled_time, s.model_prob_entry,
              s.market_prob_entry, s.edge_entry, s.market_result, s.realized_pnl,
              (SELECT e.drivers_json FROM edge_history e
                WHERE e.ticker = s.ticker AND e.cache_miss = 0
                  AND e.timestamp <= CAST(strftime('%s', s.settled_time) AS INTEGER)
                ORDER BY e.timestamp DESC LIMIT 1) AS drivers_json
       FROM settlements s
       WHERE s.model_prob_entry IS NOT NULL
         AND LOWER(s.market_result) IN ('yes', 'no')
         AND NOT EXISTS (
           SELECT 1 FROM lessons l
            WHERE l.ticker = s.ticker AND l.settled_time = s.settled_time
         )
       ORDER BY s.settled_time DESC
       LIMIT ?`,
    )
    .all(limit) as PendingSettlement[];
}

/** Deterministic lesson when no LLM is available or the call fails. */
export function fallbackLesson(s: PendingSettlement): string {
  const outcome = s.market_result.toLowerCase() === 'yes' ? 1 : 0;
  const missPp = Math.round((s.model_prob_entry - outcome) * 100);
  const direction = missPp > 0 ? 'overconfident on YES' : 'overconfident on NO';
  const cat = categoryOf(s.event_ticker, s.ticker);
  if (Math.abs(missPp) <= 20) {
    return `${cat}: model ${Math.round(s.model_prob_entry * 100)}% vs outcome ${outcome ? 'YES' : 'NO'} — within tolerance; no correction indicated.`;
  }
  return `${cat}: model was ${direction} by ${Math.abs(missPp)}pp (said ${Math.round(s.model_prob_entry * 100)}%, outcome ${outcome ? 'YES' : 'NO'}); discount similar ${cat} signals until calibration recovers.`;
}

function buildPrompt(s: PendingSettlement): string {
  const outcome = s.market_result.toLowerCase() === 'yes' ? 'YES' : 'NO';
  const drivers = s.drivers_json ? `\nDrivers cited at entry: ${s.drivers_json.slice(0, 600)}` : '';
  return [
    `A prediction-market position settled. Write ONE terse, falsifiable lesson (max 30 words) about the forecasting error or success, usable when analyzing similar markets. No preamble, no hedging boilerplate.`,
    '',
    `Market: ${s.ticker} (event ${s.event_ticker})`,
    `Model probability at entry: ${Math.round(s.model_prob_entry * 100)}%`,
    s.market_prob_entry !== null ? `Market price at entry: ${Math.round(s.market_prob_entry * 100)}%` : '',
    `Outcome: ${outcome}`,
    `Realized P&L: ${s.realized_pnl >= 0 ? '+' : ''}$${s.realized_pnl.toFixed(2)}${drivers}`,
  ].filter(Boolean).join('\n');
}

export interface ReflectResult {
  generated: number;
  source: 'llm' | 'fallback' | 'mixed' | 'none';
}

/**
 * Generate lessons for settlements that don't have one. `llm` is injectable
 * for tests; production passes a fast-model wrapper.
 */
export async function generateMissingLessons(
  db: Database,
  opts: { llm?: LessonLlm; limit?: number } = {},
): Promise<ReflectResult> {
  const pending = getPendingReflections(db, opts.limit ?? 10);
  if (pending.length === 0) return { generated: 0, source: 'none' };

  let llmCount = 0;
  let fallbackCount = 0;
  let inserted = 0;
  const insert = db.prepare(
    `INSERT OR IGNORE INTO lessons (
       ticker, event_ticker, category, settled_time, model_prob, market_prob,
       outcome, realized_pnl, lesson, source, created_at
     ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
  );

  for (const s of pending) {
    let lesson: string | null = null;
    let source = 'fallback';
    if (opts.llm) {
      try {
        const raw = (await opts.llm(buildPrompt(s))).trim();
        if (raw) {
          lesson = raw.split('\n')[0].slice(0, 300);
          source = 'llm';
          llmCount++;
        }
      } catch {
        // fall through to deterministic lesson
      }
    }
    if (!lesson) {
      lesson = fallbackLesson(s);
      fallbackCount++;
    }
    const res = insert.run(
      s.ticker,
      s.event_ticker,
      categoryOf(s.event_ticker, s.ticker),
      s.settled_time,
      s.model_prob_entry,
      s.market_prob_entry,
      s.market_result.toLowerCase() === 'yes' ? 1 : 0,
      s.realized_pnl,
      lesson,
      source,
      Math.floor(Date.now() / 1000),
    );
    inserted += res.changes;
  }

  const source: ReflectResult['source'] =
    llmCount > 0 && fallbackCount > 0 ? 'mixed' : llmCount > 0 ? 'llm' : 'fallback';
  return { generated: inserted, source };
}

/** Lessons for a category, newest first — the injection read path. */
export function getLessonsForCategory(db: Database, category: string, limit = 3): LessonRow[] {
  return db
    .prepare(
      `SELECT * FROM lessons WHERE category = ? ORDER BY created_at DESC, id DESC LIMIT ?`,
    )
    .all(category, limit) as LessonRow[];
}

export function getRecentLessons(db: Database, limit = 15): LessonRow[] {
  return db
    .prepare(`SELECT * FROM lessons ORDER BY created_at DESC, id DESC LIMIT ?`)
    .all(limit) as LessonRow[];
}

/** Compact block for prompt/report injection. Empty string when no lessons. */
export function formatLessonsForContext(lessons: LessonRow[]): string {
  if (lessons.length === 0) return '';
  const lines = ['Lessons from settled positions in this series:'];
  for (const l of lessons) {
    lines.push(`  - [${l.settled_time.slice(0, 10)}] ${l.lesson}`);
  }
  return lines.join('\n');
}
